def read_order_ids(page):
    """读当前列表(vxe 表格)可见的平台订单号（去重）。订单号形如 P2AM6TCD63208。
    用于物流下单时记下【本渠道】订单号，透传给 WMS 精确勾选、只发本渠道的单
    （修跨渠道误改快递方漏洞，用户 2026-07-17）。固定列会让行翻倍，故用 Set 去重。"""
    try:
        ids = page.evaluate(r"""() => {
            const s = new Set();
            document.querySelectorAll('.vxe-body--row').forEach(r => {
                const m = (r.innerText || '').match(/P[0-9A-Z]{9,15}/g);
                if (m) m.forEach(x => s.add(x));
            });
            return [...s];
        }""")
        return ids or []
    except Exception:
        return []

